        '{% extends "base.html" %}\n{% block title %}Play{% endblock %}\n{% block content %}\n<div class="game-layout">\n  <section class="card" aria-label="Current game">\n    {% if game %}\n      <div class="badges">\n        <span class="badge">{{ game.difficulty }}</span>\n        <span class="badge badge-category"><span class="icon" aria-hidden="true">{% include "icons/tag.svg" %}</span> {{ game.category }}</span>\n        {% if game.category == "Daily" %}\n        <span class="badge badge-daily"><span class="icon" aria-hidden="true">{% include "icons/sparkles.svg" %}</span> Daily challenge</span>\n        {% endif %}\n      </div>\n      <figure class="stage">\n        <svg id="hangman-svg" viewBox="0 0 200 220" role="img" aria-label="Hangman drawing, {{ game.wrong_count }} wrong guesses">\n          <g class="gallows" fill="none" stroke-linecap="round">\n            <path d="M20 200 H120" />\n            <path d="M60 200 V20" />\n            <path d="M60 20 H150" />\n            <path d="M150 20 V45" />\n          </g>\n          <g class="part" data-part="1" {% if parts_visible < 1 %}style="display:none"{% endif %}><circle cx="150" cy="60" r="15" fill="none" /></g>\n          <g class="part" data-part="2" {% if parts_visible < 2 %}style="display:none"{% endif %}><path d="M150 75 V130" fill="none" /></g>\n          <g class="part" data-part="3" {% if parts_visible < 3 %}style="display:none"{% endif %}><path d="M150 90 L125 115" fill="none" /></g>\n          <g class="part" data-part="4" {% if parts_visible < 4 %}style="display:none"{% endif %}><path d="M150 90 L175 115" fill="none" /></g>\n          <g class="part" data-part="5" {% if parts_visible < 5 %}style="display:none"{% endif %}><path d="M150 130 L130 168" fill="none" /></g>\n          <g class="part" data-part="6" {% if parts_visible < 6 %}style="display:none"{% endif %}><path d="M150 130 L170 168" fill="none" /></g>\n        </svg>\n      </figure>\n      <div class="letters" id="letters" aria-label="Word to guess">\n        {% for ch in game.masked_letters %}<span class="letter">{{ ch }}</span>{% endfor %}\n      </div>\n      <p class="sr-only">{{ game.masked_display }}</p>\n      <div class="meta">\n        <p id="attempts-text">{{ game.remaining }} of {{ game.max_attempts }} attempts left</p>\n        <div class="hearts" id="hearts" aria-hidden="true" data-max="{{ game.max_attempts }}">\n          {% for i in range(game.max_attempts) %}<span class="heart{% if i >= game.remaining %} lost{% endif %}">{% include "icons/heart.svg" %}</span>{% endfor %}\n        </div>\n        <p>Guessed: <span id="guessed-list">{% for letter in game.guessed|sort %}<span class="chip">{{ letter|upper }}</span>{% else %}<span class="dim">none yet</span>{% endfor %}</span></p>\n        <p class="score-line">Score: <strong id="score">{{ game.live_score() }}</strong></p>\n      </div>\n      <div id="result-panel" class="result" {% if not game.is_finished %}hidden{% endif %}>\n        <h2 id="result-title">{% if game.status == "won" %}You won!{% elif game.status == "lost" %}Game over{% endif %}</h2>\n        <p>The word was <strong id="result-answer">{{ answer or "" }}</strong></p>\n        <p>Final score: <strong id="result-score">{{ game.final_score() if game.is_finished else "" }}</strong></p>\n        <p><a class="btn" href="{{ url_for(\'game.submit_score_form\') }}">Save your score</a></p>\n      </div>\n      <div id="game-state" data-status="{{ game.status }}" data-wrong="{{ game.wrong_count }}" data-max="{{ game.max_attempts }}" hidden></div>\n    {% else %}\n      <h1>Guess the hidden word</h1>\n      <p>Pick a difficulty and a category, then guess one letter at a time before you run out of attempts.</p>\n      <ul class="howto">\n        <li><strong>Easy</strong> gives 8 attempts, <strong>Medium</strong> 6, <strong>Hard</strong> 5.</li>\n        <li>Repeating a letter never costs an attempt.</li>\n        <li>Hints reveal a letter but cost 15 points each.</li>\n        <li>Finish the game, enter your name, and land on the leaderboard.</li>\n      </ul>\n    {% endif %}\n  </section>\n  <aside class="side">\n    {% if game and not game.is_finished %}\n    <section class="card" id="guess-card" aria-label="Make a guess">\n      <h2><span class="icon" aria-hidden="true">{% include "icons/keyboard.svg" %}</span> Your guess</h2>\n      <form id="guess-form" action="{{ url_for(\'game.guess\') }}" method="post">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}">\n        <label class="sr-only" for="letter">Letter</label>\n        <input id="letter" name="letter" maxlength="1" minlength="1" required pattern="[A-Za-z]" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="A" aria-label="Guess a letter">\n        <button type="submit">Guess</button>\n      </form>\n      <p id="guess-message" role="status" aria-live="polite"></p>\n    </section>\n    <section class="card" id="hint-card" aria-label="Hint and give up">\n      <h2><span class="icon" aria-hidden="true">{% include "icons/lightbulb.svg" %}</span> Stuck?</h2>\n      <form id="hint-form" action="{{ url_for(\'game.hint\') }}" method="post">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}">\n        <button type="submit" class="secondary">Reveal a letter (-15 pts)</button>\n      </form>\n      <form id="giveup-form" action="{{ url_for(\'game.give_up\') }}" method="post">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}">\n        <button type="submit" class="linklike">Give up and reveal the word</button>\n      </form>\n    </section>\n    {% endif %}\n    <section class="card" aria-label="New game">\n      <h2><span class="icon" aria-hidden="true">{% include "icons/play.svg" %}</span> New game</h2>\n      <form action="{{ url_for(\'game.new_game\') }}" method="post">\n        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}">\n        <fieldset>\n          <legend>Difficulty</legend>\n          {% for level in difficulties %}\n          <label class="radio"><input type="radio" name="difficulty" value="{{ level }}" {% if level == "Medium" %}checked{% endif %}> {{ level }}</label>\n          {% endfor %}\n        </fieldset>\n        <label class="field">Category\n          <select name="category">\n            {% for cat in categories %}<option value="{{ cat }}">{{ cat }}</option>{% endfor %}\n          </select>\n        </label>\n        <button type="submit">{% if game and game.is_finished %}Play again{% else %}Start game{% endif %}</button>\n      </form>\n      <p><a class="btn-secondary" href="{{ url_for(\'game.daily\') }}">Play the daily challenge</a></p>\n    </section>\n  </aside>\n</div>\n{% endblock %}\n'
